/**
 * @param {string} path
 * @param {RequestInit} [options={}]
 * @returns {Promise<any>}
 */
async function request(path, options = {}) {
    const res = await fetch(`${API_BASE}${path}`, {
        ...options,
        headers: {
            "Content-Type": "application/json",
            ...options.headers,
        },
    });

    const text = await res.text();

    if (!res.ok) {
        throw new Error(
            `${options.method ?? "GET"} ${path} failed: ${res.status} ${text}`
        );
    }

    if (!text) {
        return null;
    }

    return JSON.parse(text);
}

async function main() {
    console.log("Creating user...");

    try {
        await request("/users", {
            method: "POST",
            body: JSON.stringify(userBody),
        });

        console.log("User created");
    } catch {
        console.log("User already exists, continuing...");
    }

    console.log("Logging in...");

    const auth = await request("/tokens", {
        method: "POST",
        body: JSON.stringify({
            username: userBody.username,
            password: userBody.password,
        }),
    });

    const token = auth.token;

    console.log("Adding restaurants...");

    // Fetch what already exists and only create what is missing,
    // so manual data is never touched and re-running never duplicates fixtures.
    /** @type {any[]} */
    const existingRestaurants = (await request("/restaurants")) ?? [];
    const restaurantByName = new Map(
        existingRestaurants.map((r) => [r.name, r])
    );

    const createdRestaurants = [];

    for (const restaurant of restaurants) {
        let createdRestaurant = restaurantByName.get(restaurant.name);

        if (createdRestaurant) {
            console.log("Exists:", createdRestaurant.name);
        } else {
            createdRestaurant = await request("/restaurants", {
                method: "POST",
                headers: {
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify(restaurant),
            });
            restaurantByName.set(createdRestaurant.name, createdRestaurant);
            console.log("Added:", createdRestaurant.name);
        }

        createdRestaurants.push(createdRestaurant);
    }

    console.log("Adding products...");

    const createdProductsByRestaurant = [];

    for (const group of productsByRestaurant) {
        const restaurant = createdRestaurants[group.restaurantIndex];

        // Only add products this restaurant does not already have.
        /** @type {any[]} */
        const existingProducts =
            (await request(`/restaurants/${restaurant.id}/products`)) ?? [];
        const productByName = new Map(
            existingProducts.map((p) => [p.name, p])
        );

        const createdProducts = [];

        for (const product of group.products) {
            let createdProduct = productByName.get(product.name);

            if (createdProduct) {
                console.log("Exists product:", createdProduct.name);
            } else {
                createdProduct = await request(
                    `/restaurants/${restaurant.id}/products`,
                    {
                        method: "POST",
                        headers: {
                            Authorization: `Bearer ${token}`,
                        },
                        body: JSON.stringify(product),
                    }
                );
                console.log("Added product:", createdProduct.name);
            }

            createdProducts.push(createdProduct);
        }

        createdProductsByRestaurant.push({
            restaurant,
            products: createdProducts,
        });
    }

    console.log("Adding orders...");

    const orders = [
        {
            restaurant: createdProductsByRestaurant[0].restaurant.id,
            content: [
                createdProductsByRestaurant[0].products[0].id,
                createdProductsByRestaurant[0].products[1].id,
                createdProductsByRestaurant[0].products[3].id,
            ],
        },
        {
            restaurant: createdProductsByRestaurant[5].restaurant.id,
            content: [
                createdProductsByRestaurant[5].products[0].id,
                createdProductsByRestaurant[5].products[1].id,
                createdProductsByRestaurant[5].products[2].id,
            ],
        },
    ];

    // Skip orders that already exist (same restaurant + same items).
    /** @type {any[]} */
    const existingOrders =
        (await request("/orders", {
            headers: { Authorization: `Bearer ${token}` },
        })) ?? [];
    /** @param {any} o */
    const orderSignature = (o) =>
        `${o.restaurant}|${[...o.content].sort((a, b) => a - b).join(",")}`;
    const seenOrders = new Set(existingOrders.map(orderSignature));

    for (const order of orders) {
        if (seenOrders.has(orderSignature(order))) {
            console.log("Exists order for restaurant:", order.restaurant);
            continue;
        }

        try {
            await request("/orders", {
                method: "POST",
                headers: {
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify(order),
            });
            seenOrders.add(orderSignature(order));

            console.log("Added order for restaurant:", order.restaurant);
        } catch (err) {
            console.log(
                "Skipped order for restaurant:",
                order.restaurant,
                err instanceof Error ? err.message : err
            );
        }
    }

    console.log("Checking orders...");

    const createdOrders = await request("/orders", {
        headers: {
            Authorization: `Bearer ${token}`,
        },
    });

    console.log(createdOrders);

    console.log("Seed finished");
}

main().catch((err) => {
    console.error("Seed failed:");
    console.error(err.message);
    process.exit(1);
});